import math
    import random
    import time

    LANGUAGE_WRAPPER = "Let $S$ be an arithmetic progression of {n} terms with first term {b} and common difference {a}. For each non-empty subset of $S$, a 'weighted alternating sum' is defined. The weighted alternating sum of a subset is its size multiplied by its alternating sum. The alternating sum is found by listing the elements in decreasing order and alternately adding and subtracting them. For example, for a subset $\\{c_1, c_2, c_3\\}$ with $c_1>c_2>c_3$, its alternating sum is $c_1-c_2+c_3$ and its weighted alternating sum is $3(c_1-c_2+c_3)$. Find the sum of the weighted alternating sums over all non-empty subsets of $S$."

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
n = rng.randint(5, 12)
a = rng.randint(1, 5)
b = rng.randint(1, 5)
return {
    'n': n,
    'a': a,
    'b': b
}

    def verifier(assign):
n = assign['n']
a = assign['a']
b = assign['b']

# The problem is non-trivial for n >= 2.
# The generator ensures n >= 5, but we check for robustness.
if n < 2:
    # For n=1, the set is {b}. The only non-empty subset is {b}.
    # Alt sum is b. Weighted alt sum is 1*b = b. Total sum is b.
    # The general formula does not hold for n=1.
    if n == 1:
        return True, b
    return False, None # n=0 or negative is invalid.

# The sum of weighted alternating sums for an arithmetic progression
# with n terms (x_1, ..., x_n), first term b, common difference a is:
# Sum = x_{n-1} * (-2^{n-2}) + x_n * (n+1)2^{n-2}
# where x_k = b + (k-1)a.
# This simplifies to 2^{n-2} * [n*b + (n^2-n+1)*a].

try:
    # Use integer arithmetic to avoid floating point issues.
    # 1 << (n-2) is equivalent to 2**(n-2)
    pow2_term = 1 << (n - 2)

    term_b = n * b
    term_a = (n*n - n + 1) * a

    answer = pow2_term * (term_b + term_a)
except Exception as e:
    # Catch potential overflow or other math errors, though unlikely with Python's arbitrary precision integers.
    return False, None

return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

